    document.body.classList.add('auth-pendente');
    document.body.classList.add('auth-saiu');

    const telaLogin = document.getElementById('telaProtecaoAcesso');
    if(telaLogin) telaLogin.classList.add('hidden');

    const authSenha = document.getElementById('authSenha');
    if(authSenha) authSenha.value = '';

    const erro = document.getElementById('authErro');
    if(erro){
        erro.classList.add('hidden');
        erro.textContent = '';
