    const telaEncerramento = document.getElementById('telaEncerramentoAcesso');
    if(telaEncerramento) telaEncerramento.classList.remove('hidden');

    window.scrollTo(0, 0);

    // Tenta fechar uma janela/PWA quando o navegador permitir.
    // Em abas normais o navegador pode bloquear window.close(); nesse caso,
    // a tela de encerramento permanece visível em vez de deixar uma tela branca.
    setTimeout(() => {
        try { window.close(); } catch(e) {}
    }, 120);
}

