function salvarSessaoNuvemManual(sessao) {
    try {
        // O retorno de signInWithPassword é a fonte da verdade.
        // Não rejeitamos a sessão apenas porque algum campo opcional
        // (como refresh_token) não veio no formato esperado.
        if (!sessao || !sessao.access_token) {
            console.error('Sessão Supabase sem access_token:', sessao);
            return false;
        }

        const registro = {
            access_token: String(sessao.access_token),
            refresh_token: sessao.refresh_token ? String(sessao.refresh_token) : null,
            expires_at: sessao.expires_at ?? null,
            expires_in: sessao.expires_in ?? null,
            token_type: sessao.token_type || 'bearer',
            user: sessao.user || null,
            gravada_em: new Date().toISOString()
        };

        const texto = JSON.stringify(registro);
        pfdLocal.setItem(CHAVE_SESSAO_NUVEM_MANUAL, texto);

        // Confirma imediatamente a gravação. Se falhar aqui,
        // então temos de fato um problema de armazenamento do navegador.
        const confirmacao = pfdLocal.getItem(CHAVE_SESSAO_NUVEM_MANUAL);
        if (!confirmacao) {
            console.error('pfdLocal não devolveu a sessão recém-gravada.');
            return false;
        }

        const conferido = JSON.parse(confirmacao);
        if (!conferido?.access_token) {
            console.error('Sessão gravada, mas sem access_token.');
            return false;
        }

        sessaoNuvemManual = registro;
        return true;
    } catch (e) {
        console.error('Falha real ao gravar sessão manual:', e);
        return false;
    }
}

function obterSessaoNuvemManual() {
    try {
        if (sessaoNuvemManual?.access_token) return sessaoNuvemManual;
        const salvo = pfdLocal.getItem(CHAVE_SESSAO_NUVEM_MANUAL);
        if (!salvo) return null;
        const registro = JSON.parse(salvo);
        // O access_token é suficiente para as chamadas REST autenticadas.
        // O refresh_token é desejável, mas não pode ser requisito para usar
        // uma sessão recém-obtida no mesmo navegador.
        if (!registro?.access_token) return null;
        sessaoNuvemManual = registro;
        return registro;
    } catch (e) {
        return null;
    }
}

async function restaurarSessaoNuvemManual() {
    const sessao = obterSessaoNuvemManual();
    if (!sessao || !supabaseCliente) return sessao || null;
    try {
        if (sessao.refresh_token) {
            const { data, error } = await supabaseCliente.auth.setSession({
                access_token: sessao.access_token,
                refresh_token: sessao.refresh_token
            });
            if (!error && data?.session) {
                sessaoNuvemManual = data.session;
                salvarSessaoNuvemManual(data.session);
                return data.session;
            }
            if (error) console.warn('Supabase setSession:', error);
        }
    } catch (e) {
        console.warn('Não foi possível restaurar a sessão no cliente Supabase:', e);
    }
    // Mesmo sem sessão interna do cliente, devolvemos a sessão manual.
    // As operações de banco da V3.4 usarão o JWT diretamente no REST.
    return sessao;
}

async function obterSessaoAutenticadaNuvem() {
    if (!supabaseCliente && !inicializarSupabaseCliente()) return null;
    try {
        const { data, error } = await supabaseCliente.auth.getSession();
        if (!error && data?.session?.access_token) {
            sessaoNuvemManual = data.session;
            return data.session;
        }
    } catch (e) {
        console.warn('Supabase getSession exception:', e);
    }

    const manual = obterSessaoNuvemManual();
    if (!manual?.access_token) return null;

    // Se houver refresh token, tenta renovar a sessão antes de usar o JWT.
    if (manual.refresh_token) {
        try {
            const { data, error } = await supabaseCliente.auth.setSession({
                access_token: manual.access_token,
                refresh_token: manual.refresh_token
            });
            if (!error && data?.session?.access_token) {
                sessaoNuvemManual = data.session;
                salvarSessaoNuvemManual(data.session);
                return data.session;
            }
        } catch (e) {
            console.warn('Renovação da sessão Supabase:', e);
        }
    }
    return manual;
}

