async function entrarNuvem() {
    const btn = document.querySelector('#modalConfiguracaoNuvem button[onclick="entrarNuvem()"]');
    try {
        if (!supabaseCliente && !inicializarSupabaseCliente()) {
            throw new Error('Biblioteca Supabase não foi carregada. Atualize a página e tente novamente.');
        }
        const emailEl = document.getElementById('nuvemEmail');
        const senhaEl = document.getElementById('nuvemSenha');
        const email = (emailEl?.value || '').trim().toLowerCase();
        const password = senhaEl?.value || '';
        if (!email || !password) throw new Error('Informe o e-mail e a senha da conta de sincronização.');

        if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1"></i> Conectando...'; }
        atualizarStatusNuvem('Conectando ao Supabase...');

        // Limpa uma sessão antiga somente deste dispositivo antes de autenticar.
        try { await supabaseCliente.auth.signOut({ scope: 'local' }); } catch (_) {}
        const { data, error } = await supabaseCliente.auth.signInWithPassword({ email, password });
        if (error) throw error;
        if (!data?.session?.access_token) throw new Error('O Supabase aceitou o login, mas não devolveu uma sessão. Verifique se a conta está confirmada.');

        // V3.3 — correção de sessão: não dependemos exclusivamente do storage interno do Supabase.
        // O próprio retorno do login já contém uma sessão válida; gravamos essa
        // sessão no pfdLocal do site e a restauramos nas próximas aberturas.
        const sessaoLogin = data.session;

        // Primeiro confirmamos a sessão recebida e a gravação local.
        if (!salvarSessaoNuvemManual(sessaoLogin)) {
            throw new Error('O Supabase aceitou o login, mas a sessão não pôde ser confirmada no armazenamento local deste site.');
        }

        // O Supabase também pode manter sua própria sessão. Se houver
        // refresh_token, tentamos registrá-la normalmente; a cópia manual
        // acima continua sendo a contingência do aplicativo.
        let sessionConfirmada = sessaoLogin;
        if (sessaoLogin.refresh_token) {
            try {
                const { data: setData, error: setError } = await supabaseCliente.auth.setSession({
                    access_token: sessaoLogin.access_token,
                    refresh_token: sessaoLogin.refresh_token
                });
                if (!setError && setData?.session) {
                    sessionConfirmada = setData.session;
                    salvarSessaoNuvemManual(sessionConfirmada);
                } else if (setError) {
                    console.warn('Supabase setSession:', setError);
                }
            } catch (setError) {
                console.warn('Supabase setSession exception:', setError);
            }
        }
        sessaoNuvemManual = sessionConfirmada || sessaoLogin;
        salvarSessaoNuvemManual(sessaoNuvemManual);

        document.getElementById('statusNuvemBadge').textContent = 'Online';
        atualizarStatusNuvem('Conta conectada. Verificando a sincronização financeira.', true);
        if (emailEl) emailEl.value = sessionConfirmada.user.email || email;

        try {
            const ok = await sincronizarNuvemAoAbrir();
            if (!ok) {
                // Autenticação está correta mesmo que a tabela/RLS esteja com problema.
                document.getElementById('statusNuvemBadge').textContent = 'Online';
                atualizarStatusNuvem('Conta conectada. O acesso ao banco precisa ser verificado.', false);
            } else {
                atualizarStatusNuvem('Conta conectada e sincronização financeira concluída.', true);
            }
        } catch (syncError) {
            document.getElementById('statusNuvemBadge').textContent = 'Online';
            const detalhe = resumirErroSupabase(syncError);
            atualizarStatusNuvem('Conta conectada, mas houve erro no banco: ' + detalhe, false);
            alert('A conta foi conectada com sucesso neste PC, mas a sincronização encontrou um erro:\n\n' + detalhe);
        }

        popularSelectsDinamicos();
        renderTable();
        atualizarPainelGerencial();
        atualizarInfoBanco();
        if (senhaEl) senhaEl.value = '';
    } catch (e) {
        console.error('Falha no login da nuvem:', e);
        document.getElementById('statusNuvemBadge').textContent = 'Local';
        const detalhe = resumirErroSupabase(e);
        atualizarStatusNuvem('Falha no login: ' + detalhe, false);
        alert('Não foi possível conectar à nuvem neste PC:\n\n' + detalhe);
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-right-to-bracket mr-1"></i> Entrar / Sincronizar'; }
    }
}

async function criarContaNuvem() {
    if (!supabaseCliente && !inicializarSupabaseCliente()) return alert('Serviço de nuvem não foi carregado. Verifique a conexão com a internet.');
    const email = document.getElementById('nuvemEmail').value.trim().toLowerCase();
    const password = document.getElementById('nuvemSenha').value;
    if (!/^\S+@\S+\.\S+$/.test(email)) return alert('Informe um e-mail válido.');
    if (password.length < 6) return alert('A senha da conta de nuvem deve ter pelo menos 6 caracteres.');
    const { data, error } = await supabaseCliente.auth.signUp({ email, password });
    if (error) return alert('Não foi possível criar a conta: ' + error.message);
    if (!data.session) {
        alert('Conta criada. Verifique o e-mail de confirmação da Supabase e depois entre por este botão.');
    } else {
        await sincronizarNuvemAoAbrir();
        alert('Conta de nuvem criada e banco sincronizado.');
    }
    document.getElementById('nuvemSenha').value='';
}

